 * Core three-way line-merge algorithm: diffing each side against the base
 * with a tie-broken longest common subsequence, then grouping the resulting
 * changes into stable and conflicting regions.
 */

/**
 * Finds the tie-broken longest common subsequence between `side` and `base`
 * and returns the stretches of `side` that were not matched, each paired
 * with the stretch of `base` it replaces.
 *
 * @param {string[]} side
 * @param {string[]} base
 * @returns {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]}
 */
function diffAgainstBase(side, base) {
  const n = side.length
  const m = base.length
  // dp[i][j] holds the LCS length of side[i:] and base[j:].
  const dp = []
  for (let i = 0; i <= n; i++) dp.push(new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i][j + 1] >= dp[i + 1][j]) {
      j++
    } else {
      i++
    }
  }
  matches.push([n, m])

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevJ, baseEnd: mj, sideStart: prevI, sideEnd: mi })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  return changes
}

/**
 * @param {string[]} a
 * @param {string[]} b
 */
function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let k = 0; k < a.length; k++) {
    if (a[k] !== b[k]) return false
  }
  return true
}

/**
 * Computes the merge of `mine` and `theirs` against `base`, expressed as an
 * ordered list of regions. Each region is either:
 * - `{ kind: 'stable', lines }` for base lines neither side touched,
 * - `{ kind: 'mine' | 'theirs' | 'both', lines }` for a clean resolution, or
 * - `{ kind: 'conflict', mine, base, theirs }` for a genuine conflict.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = diffAgainstBase(mine, base).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = diffAgainstBase(theirs, base).map(change => ({ ...change, side: 'theirs' }))

  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)

  const changeRegions = []
  let index = 0
  while (index < allChanges.length) {
    const group = [allChanges[index]]
    let baseStart = allChanges[index].baseStart
    let baseEnd = allChanges[index].baseEnd
    index++
    while (index < allChanges.length && allChanges[index].baseStart <= baseEnd) {
      baseEnd = Math.max(baseEnd, allChanges[index].baseEnd)
      group.push(allChanges[index])
      index++
    }
    changeRegions.push({ baseStart, baseEnd, changes: group })
  }

  /**
   * Extracts the lines a side contributes to a region, mapped from its own
   * changes (or straight from the base, when the side made none).
   */
  function sideLines(doc, changes, region) {
    const own = changes.filter(c => c.side === (doc === mine ? 'mine' : 'theirs'))
    if (own.length === 0) return base.slice(region.baseStart, region.baseEnd)
    let smallestStart = own[0].baseStart
    let largestEnd = own[0].baseEnd
    let first = own[0]
    let last = own[0]
    for (const c of own) {
      if (c.baseStart < smallestStart) {
        smallestStart = c.baseStart
        first = c
      }
      if (c.baseEnd > largestEnd) {
        largestEnd = c.baseEnd
        last = c
      }
    }
    const leftOffset = smallestStart - region.baseStart
    const rightOffset = region.baseEnd - largestEnd
    return doc.slice(first.sideStart - leftOffset, last.sideEnd + rightOffset)
  }

  const regions = []
  let lastEnd = 0
  for (const region of changeRegions) {
    if (region.baseStart > lastEnd) {
      regions.push({ kind: 'stable', lines: base.slice(lastEnd, region.baseStart) })
    }

    const mineLines = sideLines(mine, region.changes, region)
    const theirsLines = sideLines(theirs, region.changes, region)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    if (linesEqual(mineLines, theirsLines)) {
      regions.push({ kind: 'both', lines: mineLines })
    } else if (linesEqual(mineLines, baseLines)) {
      regions.push({ kind: 'theirs', lines: theirsLines })
    } else if (linesEqual(theirsLines, baseLines)) {
      regions.push({ kind: 'mine', lines: mineLines })
    } else {
      regions.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    lastEnd = region.baseEnd
  }
  if (lastEnd < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(lastEnd, base.length) })
  }

  return regions
}
"}

