{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-W5bhgz/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { computeRegions } from './diff3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatMerge(regions, includeBase) {
  const out = []
  let hasConflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      hasConflict = true
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (includeBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.length === 0 ? '' : `${out.join('\n')}\n`, hasConflict }
}

function formatRegions(regions) {
  const out = []
  let hasConflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      hasConflict = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { text: out.length === 0 ? '' : `${out.join('\n')}\n`, hasConflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdin()
  const documents = splitDocuments(input)
  if (documents.length !== 3) {
    fail('error: expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = documents
  const regions = computeRegions(mine, base, theirs)

  const { text, hasConflict } =
    mode === 'regions' ? formatRegions(regions) : formatMerge(regions, mode === 'merge')

  process.stdout.write(text)
  process.exit(hasConflict ? 1 : 0)
}

main()
"}

